(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-586":{scenario:{company:"Trường Sơn Electronics Design",supervisor:{name:"Bùi Ngọc Diệp",role:{vi:"Trưởng phòng Thiết kế Phần cứng",en:"Hardware Design Manager"}},ref_code:"PCB-3518",title:{vi:"Tính đúng tổn hao. Chọn đúng bộ nguồn. Báo cáo đúng nhiệt độ.",en:"Right losses. Right regulator. True temperatures."},brief:{vi:"Bo mạch PCB-3518 cấp nguồn 12 V, rail 3.3 V tải liên tục 0.35 A. Bản xét duyệt thiết kế nháp chọn LDO vỏ SOT-223 và tính sai công suất tiêu tán. Nhiệt độ môi trường trong vỏ máy tối đa 50°C, giới hạn nhiệt độ mối nối 125°C, θJA mô phỏng: SOT-223 62°C/W, DPAK 30°C/W. Đối chiếu với quy tắc thiết kế nguồn đã duyệt, sửa kiểu bộ ổn áp và công suất tiêu tán của LDO (W), rồi lập báo cáo có căn cứ.",en:"Board PCB-3518 runs from 12 V and its 3.3 V rail draws a continuous 0.35 A. The draft design review picks an SOT-223 LDO and miscalculates its dissipation. Maximum ambient inside the enclosure is 50°C, junction limit 125°C, training θJA: SOT-223 62°C/W, DPAK 30°C/W. Check it against the approved power design rules, correct the regulator type and the LDO power dissipation (W), then write an evidence-based report."},reference_title:{vi:"Quy tắc thiết kế nguồn và ngân sách công suất đã duyệt · PCB-3518",en:"Approved power design rules and power budget · PCB-3518"},fields:[{id:"REG_TYPE",label:{vi:"Kiểu bộ ổn áp rail 3.3 V",en:"3.3 V rail regulator type"},initial:"LDO-SOT223",expected:"BUCK-SYNC",choices:["LDO-SOT223","LDO-DPAK","BUCK-SYNC"],reference:"Quy tắc chọn bộ ổn áp",hint:{vi:"Kiểm tra nhiệt độ mối nối của từng phương án LDO; nếu cả hai vượt giới hạn thì phải đổi kiến trúc.",en:"Check the junction temperature of each LDO option; if both exceed the limit, change the architecture."}},{id:"P_LDO",label:{vi:"Công suất tiêu tán của LDO (W)",en:"LDO power dissipation (W)"},initial:"1.155",expected:"3.045",reference:"Bảng ngân sách công suất rail 3.3 V",ref_value:{vi:"Vin 12 V; Vout 3.3 V; dòng tải liên tục 0.35 A; bỏ qua dòng tĩnh",en:"Vin 12 V; Vout 3.3 V; continuous load 0.35 A; quiescent current ignored"},hint:{vi:"LDO tiêu tán phần điện áp chênh lệch nhân dòng tải, không phải công suất ra tải.",en:"An LDO dissipates the voltage drop times load current, not the output power."}}],sop32:{vi:"P_LDO = (Vin - Vout) x Iout (bỏ qua dòng tĩnh); Tj = Ta + P_LDO x θJA phải ≤ 125°C. Nếu không phương án LDO nào đạt thì dùng bộ hạ áp đồng bộ BUCK-SYNC.",en:"P_LDO = (Vin - Vout) x Iout (quiescent current ignored); Tj = Ta + P_LDO x θJA must be ≤ 125°C. If no LDO option passes, use the synchronous buck BUCK-SYNC."},context:{label:"EDA DESIGN REVIEW / PCB-3518",metrics:[{label:{vi:"Điện áp vào / ra",en:"Input / output voltage"},value:"12 V / 3.3 V"},{label:{vi:"Dòng tải liên tục",en:"Continuous load"},value:"0.35 A"},{label:{vi:"Nhiệt độ môi trường tối đa",en:"Maximum ambient"},value:"50°C"}]},terminal:{system:"eda-shell",settable:["REG_TYPE","P_LDO"],commands:[{cmd:"status",out:{vi:"PCB-3518 rev A, 4 lớp; U5 ổn áp rail 3.3 V; bản xét duyệt nháp REG_TYPE=LDO-SOT223, P_LDO=1.155",en:"PCB-3518 rev A, 4 layers; U5 regulates the 3.3 V rail; draft review REG_TYPE=LDO-SOT223, P_LDO=1.155"}},{cmd:"cat power_budget.txt",out:{vi:"Rail 3.3 V: vi điều khiển 120 mA, mô-đun vô tuyến 180 mA, cảm biến và đèn báo 50 mA; tổng 0.35 A liên tục; nguồn vào 12 V",en:"3.3 V rail: MCU 120 mA, radio module 180 mA, sensors and LEDs 50 mA; total 0.35 A continuous; 12 V input"}},{cmd:"cat u5_options.txt",out:{vi:"LDO-SOT223 θJA 62°C/W; LDO-DPAK θJA 30°C/W; BUCK-SYNC hiệu suất khoảng 90% ở 0.35 A (số liệu mô phỏng)",en:"LDO-SOT223 θJA 62°C/W; LDO-DPAK θJA 30°C/W; BUCK-SYNC about 90% efficient at 0.35 A (training data)"}},{cmd:"cat enclosure.txt",out:{vi:"Vỏ kín IP54, nhiệt độ môi trường bên trong tối đa 50°C; giới hạn mối nối linh kiện 125°C",en:"Sealed IP54 enclosure, internal ambient up to 50°C; component junction limit 125°C"}},{cmd:"thermal-scan proto",out:{vi:"Mẫu thử sau 10 phút: bề mặt U5 trên 118°C, rail 3.3 V sụt định kỳ do bảo vệ quá nhiệt tác động",en:"Prototype after 10 minutes: U5 surface above 118°C, 3.3 V rail drops periodically as thermal shutdown cycles"}}]},crisis:{vi:"Giám đốc dự án nhắn: “Khách cần hồ sơ phát hành sản xuất ngày mai. Cứ ghi mục thử nhiệt là PASS, đổi thiết kế sau ở rev B, khách không đo lại đâu.”",en:"The project director messages: “The client needs the production release file tomorrow. Just mark the thermal test PASS, we will change the design in rev B, the client will not retest.”"},options:{safe:{vi:"Từ chối ghi PASS; ghi đúng kết quả thử nhiệt, báo trưởng phòng và khách về rủi ro, đề xuất đổi U5 sang BUCK-SYNC và thử lại trước khi phát hành.",en:"Refuse to mark PASS; record the true thermal result, inform the manager and client of the risk, propose changing U5 to BUCK-SYNC and retest before release."},shortcut:{vi:"Ghi PASS để kịp phát hành, sửa thiết kế ở bản rev B.",en:"Mark PASS to meet the release and fix the design in rev B."},wait:{vi:"Để trống mục thử nhiệt và chờ giám đốc dự án tự điền.",en:"Leave the thermal test blank and wait for the project director to fill it in."}},questions:{vi:["Vì sao công suất tiêu tán đúng là 3.045 W và cả hai phương án LDO đều không đạt? Tính Tj cho từng phương án.","Ghi PASS sai cho mục thử nhiệt gây rủi ro gì cho người dùng, khách hàng và công ty? Bạn xử lý áp lực tiến độ ra sao?"],en:["Why is the correct dissipation 3.045 W and why do both LDO options fail? Compute Tj for each option.","What risks does a false thermal PASS create for users, the client and the company? How do you handle the schedule pressure?"]},hints:{vi:["Đặt bản xét duyệt nháp cạnh bảng ngân sách công suất và kiểm tra công thức tổn hao.","Áp dụng SOP mục 3.2: tính tổn hao rồi nhân với θJA của từng vỏ, cộng nhiệt độ môi trường.","Đọc lại SOP mục 4.2: kết quả thử nghiệm phải ghi đúng như đo, không được điền trước."],en:["Place the draft review next to the power budget and check the loss formula.","Apply SOP 3.2: compute the loss, multiply by each package θJA and add ambient.","Re-read SOP 4.2: test results must be recorded as measured, never filled in beforehand."]}},learning:{summary:{vi:"Kỹ sư Điện tử và Thiết kế Mạch in thiết kế sơ đồ nguyên lý, chọn linh kiện, bố trí và đi dây bo mạch nhiều lớp, tính nguồn, nhiệt, tín hiệu tốc độ cao và chuẩn bị hồ sơ sản xuất. Mục tiêu là bo mạch chạy ổn định, đạt tương thích điện từ, an toàn, dễ sản xuất và giá thành hợp lý. Công việc đòi hỏi vững mạch tương tự, số, nguồn, đọc kỹ datasheet và trung thực với kết quả thử nghiệm.",en:"An Electronics and PCB Design Engineer creates schematics, selects components, places and routes multilayer boards, analyses power, thermal and high-speed signals and prepares manufacturing files. The goal is a board that runs reliably, passes EMC and safety, is easy to build and is cost-effective. The role requires solid analogue, digital and power skills, careful datasheet reading and honesty about test results."},responsibilities:{vi:["Thiết kế sơ đồ nguyên lý, chọn linh kiện theo thông số, tuổi thọ và nguồn cung.","Bố trí linh kiện, xếp lớp, đi dây trở kháng kiểm soát và mặt phẳng nguồn, đất.","Tính ngân sách công suất, nhiệt, độ rộng đường mạch và kiểm tra DRC, ERC.","Chuẩn bị Gerber, danh mục linh kiện, tọa độ gắp đặt và hồ sơ lắp ráp.","Thử nghiệm mẫu: chức năng, nhiệt, EMC sơ bộ và sửa lỗi phần cứng."],en:["Draw schematics and select parts by ratings, lifetime and supply availability.","Place components, define stack-up and route controlled-impedance traces and power and ground planes.","Compute power, thermal and trace-width budgets and run DRC and ERC.","Prepare Gerbers, BOM, pick-and-place data and assembly drawings.","Test prototypes: function, thermal and EMC pre-scan, and debug hardware."]},competencies:[{name:{vi:"Thiết kế mạch nguồn",en:"Power circuit design"},desc:{vi:"Chọn LDO hay bộ chuyển mạch, tính tổn hao, gợn sóng, đáp ứng quá độ và nhiệt.",en:"Choose LDO or switching regulators and compute losses, ripple, transient response and thermal load."}},{name:{vi:"Bố trí mạch in",en:"PCB layout"},desc:{vi:"Đặt linh kiện tối ưu đường dòng, tách vùng nhiễu, giữ vòng dòng nhỏ.",en:"Place parts for clean current paths, separate noisy areas and keep loops small."}},{name:{vi:"Toàn vẹn tín hiệu",en:"Signal integrity"},desc:{vi:"Kiểm soát trở kháng, phản xạ, nhiễu xuyên kênh và đường hồi tiếp tín hiệu.",en:"Control impedance, reflections, crosstalk and signal return paths."}},{name:{vi:"Thiết kế cho sản xuất",en:"Design for manufacturing"},desc:{vi:"Áp dụng chuẩn chân hàn, khoảng cách, điểm thử để lắp ráp và kiểm tra hiệu quả.",en:"Apply land pattern, spacing and test point rules for efficient assembly and test."}},{name:{vi:"Trung thực trong thử nghiệm",en:"Test integrity"},desc:{vi:"Ghi đúng kết quả đo, báo sớm rủi ro và không phát hành khi thiết kế chưa đạt.",en:"Record results as measured, flag risks early and never release a failing design."}}],knowledge:{vi:["IPC-2221 về nguyên tắc chung thiết kế mạch in; IPC-2152 về khả năng mang dòng của đường mạch.","IPC-7351 về chân hàn linh kiện dán bề mặt; IPC-A-610 về tiêu chí chấp nhận cụm lắp ráp điện tử.","Nhiệt học linh kiện: θJA, θJC, công suất tiêu tán và giới hạn nhiệt độ mối nối.","CISPR 32 về phát xạ điện từ của thiết bị đa phương tiện; IEC 62368-1 về an toàn thiết bị ICT.","Chỉ thị RoHS 2011/65/EU về hạn chế chất nguy hại trong thiết bị điện, điện tử."],en:["IPC-2221 generic PCB design standard; IPC-2152 on trace current-carrying capacity.","IPC-7351 on surface-mount land patterns; IPC-A-610 on acceptability of electronic assemblies.","Component thermal behaviour: θJA, θJC, power dissipation and junction temperature limits.","CISPR 32 on emissions of multimedia equipment; IEC 62368-1 on ICT equipment safety.","RoHS Directive 2011/65/EU restricting hazardous substances in electrical and electronic equipment."]},tools:["Phần mềm thiết kế sơ đồ và mạch in","Phần mềm mô phỏng mạch SPICE","Máy hiện sóng và nguồn lập trình","Camera nhiệt","Máy phân tích phổ cho thử EMC sơ bộ"],kpis:{vi:["Số lần sửa bo (respin) trước khi phát hành sản xuất.","Tỷ lệ bo đạt thử EMC và an toàn ngay lần đầu.","Tỷ lệ lỗi lắp ráp liên quan thiết kế trên dây chuyền.","Độ chính xác của danh mục linh kiện và hồ sơ sản xuất."],en:["Board respins before production release.","Share of boards passing EMC and safety tests first time.","Design-related assembly defect rate on the line.","Accuracy of the BOM and manufacturing files."]},day:[{time:"08:30",vi:"Xem phản hồi lắp ráp mẫu và danh sách lỗi phần cứng mở.",en:"Review prototype assembly feedback and the open hardware bug list."},{time:"10:00",vi:"Tính ngân sách công suất rail mới, kiểm tra nhiệt từng bộ ổn áp.",en:"Compute the power budget for a new rail and check each regulator's thermal load."},{time:"13:30",vi:"Đi dây cặp vi sai tốc độ cao, kiểm tra trở kháng với nhà sản xuất bo.",en:"Route high-speed differential pairs and confirm impedance with the board fab."},{time:"15:30",vi:"Đo nhiệt và dạng sóng trên mẫu thử, ghi kết quả vào báo cáo thử nghiệm.",en:"Measure temperatures and waveforms on the prototype and log results in the test report."},{time:"17:00",vi:"Chạy DRC, ERC, cập nhật danh mục linh kiện và lưu phiên bản thiết kế.",en:"Run DRC and ERC, update the BOM and archive the design revision."}],mistakes:{vi:["Tính tổn hao LDO bằng công suất ra tải thay vì chênh lệch điện áp nhân dòng.","Bỏ qua nhiệt độ môi trường trong vỏ kín khi kiểm tra nhiệt độ mối nối.","Ghi kết quả thử nghiệm trước khi đo hoặc sửa số cho đạt để kịp phát hành."],en:["Computing LDO loss as output power instead of voltage drop times current.","Ignoring the sealed-enclosure ambient when checking junction temperature.","Writing test results before measuring or adjusting numbers to pass for release."]},career:[{vi:"Kỹ thuật viên điện tử",en:"Electronics technician"},{vi:"Kỹ sư thiết kế phần cứng và mạch in",en:"Hardware and PCB design engineer"},{vi:"Kỹ sư phần cứng cấp cao",en:"Senior hardware engineer"},{vi:"Trưởng phòng thiết kế phần cứng",en:"Hardware engineering manager"}],glossary:[{term:"LDO",vi:"Bộ ổn áp tuyến tính sụt áp thấp, tiêu tán phần điện áp chênh lệch thành nhiệt.",en:"Low-dropout linear regulator that turns the voltage drop into heat."},{term:"Buck converter",vi:"Bộ chuyển đổi hạ áp dùng chuyển mạch, hiệu suất cao hơn LDO khi chênh áp lớn.",en:"Switching step-down converter, more efficient than an LDO at large voltage drops."},{term:"θJA",vi:"Nhiệt trở từ mối nối tới môi trường, cho biết nhiệt độ tăng trên mỗi watt tiêu tán.",en:"Junction-to-ambient thermal resistance, the temperature rise per watt dissipated."},{term:"DRC",vi:"Kiểm tra quy tắc thiết kế như khoảng cách, độ rộng đường mạch, lỗ khoan.",en:"Design rule check covering clearance, trace width and drill rules."},{term:"Stack-up",vi:"Cấu trúc xếp lớp đồng và điện môi của bo mạch, quyết định trở kháng và EMC.",en:"Copper and dielectric layer structure of a board that sets impedance and EMC."}],quiz:[{q:{vi:"LDO hạ 5 V xuống 1.8 V cho tải 0.5 A. Công suất tiêu tán là bao nhiêu?",en:"An LDO drops 5 V to 1.8 V at 0.5 A. What is its dissipation?"},options:{vi:["0.9 W","2.5 W","1.6 W","3.2 W"],en:["0.9 W","2.5 W","1.6 W","3.2 W"]},answer:2,explain:{vi:"P = (5 - 1.8) x 0.5 = 1.6 W; lấy 1.8 x 0.5 = 0.9 W là công suất ra tải, không phải tổn hao.",en:"P = (5 - 1.8) x 0.5 = 1.6 W; 1.8 x 0.5 = 0.9 W is the output power, not the loss."}},{q:{vi:"Linh kiện tiêu tán 2 W, θJA 40°C/W, môi trường 45°C. Nhiệt độ mối nối là bao nhiêu?",en:"A part dissipates 2 W with θJA 40°C/W at 45°C ambient. What is the junction temperature?"},options:{vi:["125°C","85°C","80°C","165°C"],en:["125°C","85°C","80°C","165°C"]},answer:0,explain:{vi:"Tj = 45 + 2 x 40 = 125°C, chạm giới hạn thường gặp, không còn dự trữ.",en:"Tj = 45 + 2 x 40 = 125°C, right at a common limit with no margin."}},{q:{vi:"Giám đốc yêu cầu ghi PASS cho thử nhiệt chưa đạt để kịp phát hành. Bạn làm gì?",en:"The director asks you to mark a failed thermal test PASS to meet the release. What do you do?"},options:{vi:["Ghi PASS vì sẽ sửa ở bản sau","Để trống cho người khác điền","Ghi PASS kèm chú thích nhỏ","Ghi đúng kết quả, báo rủi ro và đề xuất sửa thiết kế trước khi phát hành"],en:["Mark PASS since rev B will fix it","Leave it blank for someone else","Mark PASS with a small footnote","Record the true result, flag the risk and propose a fix before release"]},answer:3,explain:{vi:"Làm sai lệch kết quả thử nghiệm có thể gây cháy hỏng, mất an toàn và vi phạm cam kết với khách hàng.",en:"Falsifying test results can cause failures and fire hazards and breaks commitments to the client."}},{q:{vi:"Chuẩn nào hướng dẫn khả năng mang dòng của đường mạch in?",en:"Which standard guides the current-carrying capacity of PCB traces?"},options:{vi:["IPC-A-610","IPC-2152","CISPR 32","IPC-7351"],en:["IPC-A-610","IPC-2152","CISPR 32","IPC-7351"]},answer:1,explain:{vi:"IPC-2152 cung cấp dữ liệu và biểu đồ chọn độ rộng đường mạch theo dòng và độ tăng nhiệt.",en:"IPC-2152 provides data and charts for sizing traces by current and temperature rise."}}],tools_en:["Schematic and PCB design software","SPICE circuit simulation software","Oscilloscope and programmable power supply","Thermal camera","Spectrum analyzer for EMC pre-compliance"]}}})})(window.KKR);
